-- Migration 006: Purge legacy lower-limb / orthopedic / duplicate exercises
-- and synchronize the 26 standardized Stroke ADL & MOPH Elderly upper-body exercises.

DELETE FROM public.exercises
WHERE category IN ('lower_limb', 'balance')
   OR id ~ '^ex-(0?[1-9]|[1-3][0-9]|40)$'
   OR code IN (
     'BAL_STAND_R', 'BAL_STAND_L', 'KNEE_EXT_R', 'KNEE_EXT_L',
     'HIP_FLEX_R', 'HIP_FLEX_L', 'HEEL_RAISE_R', 'HEEL_RAISE_L', 'SIT_TO_STAND',
     'SH_PEND_R', 'SH_PEND_L', 'SH_WALL_SLIDE_R', 'SH_WALL_SLIDE_L',
     'SH_FLEX_R', 'SH_FLEX_L', 'SH_ABD_R', 'SH_ABD_L',
     'ELB_FLEX_R', 'ELB_FLEX_L', 'SH_SCAP_R', 'SH_SCAP_L',
     'SH_OVH_R', 'SH_OVH_L', 'NECK_TILT_R', 'NECK_TILT_L',
     'TRUNK_SIT_STRETCH', 'MOPH_BILATERAL_ARM_RAISE'
   );

